-- Import Ottawa Painters into Hidebrandt's existing active campaign.
-- Review-only records have no roster or lead-level agent assignment.
-- Repeated source businesses and existing CRM matches are skipped.
-- No pre-existing lead or campaign is updated.
create temporary table ottawa_source on commit drop as
select n, name, nullif(phone,'') as phone, nullif(email,'') as email,
       nullif(website,'') as website, nullif(address,'') as address,
       nullif(city,'') as city, nullif(postal,'') as postal,
       nullif(category,'') as category, nullif(search_type,'') as search_type,
       nullif(source_status,'') as source_status,
       regexp_replace(lower(name),'[^a-z0-9]','','g') as name_key,
       right(regexp_replace(coalesce(phone,''),'[^0-9]','','g'),10) as phone_key,
       regexp_replace(regexp_replace(lower(coalesce(website,'')),'^https?://(www\.)?','','g'),'/$','','g') as website_key
