"postal":null,"category":"Home builder","search_type":"google","source_status":""},{"n":327,"name":"Capital Painting","phone":"6138686689","email":"","website":"","address":"","city":null,"postal":null,"category":"Painters","search_type":"yellowpages-ca","source_status":""},{"n":328,"name":"Fournier Painting And Repair","phone":"6137246874","email":"","website":"","address":"20 Anouk St, Limoges, ON K0A 2M0","city":null,"postal":"K0A 2M0","category":"Painters","search_type":"yellowpages-ca","source_status":""},{"n":329,"name":"Felix Fox Painting","phone":"16134042653","email":"","website":"","address":"335 MacLaren St, Ottawa, ON K2P 0M4, Canada","city":"Ottawa","postal":"K2P 0M4","category":"Painter","search_type":"google","source_status":""},{"n":330,"name":"Finish Coat Painting Ltd","phone":"9028002634","email":"","website":"","address":"","city":null,"postal":null,"category":"Painters","search_type":"yellowpages-ca","source_status":""}]'::jsonb)
 as r(n integer,name text,phone text,email text,website text,address text,city text,postal text,category text,search_type text,source_status text);
create temporary table ottawa_classified on commit drop as
select x.*,
 case when x.duplicate_in_file then 'duplicate_skipped'
      when x.existing_match then 'existing_matched'
      when x.phone_key = '' or x.shared_phone or x.shared_website or x.name_key = '' or x.off_category or x.generic_name
        or (x.website is not null and x.website !~* '^https?://[^ /]+\.[^ /]+')
        or x.dnc_match or x.location_conflict then 'review_required'
      when x.website is null then 'no_website'
      else 'website_review' end as bucket,
 concat_ws('; ',case when x.phone_key='' then 'Missing phone' end,
   case when x.shared_phone then 'Shared phone in CSV' end,
   case when x.shared_website then 'Shared website in CSV' end,
   case when x.generic_name then 'Generic business name; verify identity' end,
   case when x.off_category then 'Painting service not established by category/name' end,
   case when x.website is not null and x.website !~* '^https?://[^ /]+\.[^ /]+' then 'Website URL unclear' end,
   case when x.dnc_match then 'DNC suppression' end,
   case when x.location_conflict then 'Outside Ottawa/Ontario or conflicting location' end) as review_reason
from (
 select s.*,
 row_number() over(partition by s.name_key order by s.n)>1 as duplicate_in_file,
 s.phone_key<>'' and exists(select 1 from ottawa_source other where other.phone_key=s.phone_key and other.name_key<>s.name_key) as shared_phone,
 s.website_key<>'' and exists(select 1 from ottawa_source other where other.website_key=s.website_key and other.name_key<>s.name_key) as shared_website,
 s.name_key in ('painters','paintingservices','ottawapainters','housepainting') as generic_name,
 not (coalesce(s.name,'') ~* '(paint|decorat|drywall|plaster|home renovation|contractor|interior finish|wallpaper)'
   or coalesce(s.category,'') ~* '(paint|decorat|drywall|plaster|wallpaper)') or coalesce(s.category,'') ~* '(art center|line marking|parking lot|picture frame shop|association / organization|children.s party|water damage restoration|art gallery|art school)' as off_category,
 coalesce(s.address,'') ~* '(Nunavut|British Columbia|Alberta|Quebec|, QC|, BC|, AB)' as location_conflict,
 exists(select 1 from public.call_list_leads l where regexp_replace(lower(l.business_name),'[^a-z0-9]','','g')=s.name_key
   or (s.phone_key<>'' and right(regexp_replace(coalesce(l.phone,''),'[^0-9]','','g'),10)=s.phone_key)
   or (s.website_key<>'' and regexp_replace(regexp_replace(lower(coalesce(l.website,'')),'^https?://(www\.)?','','g'),'/$','','g')=s.website_key))
 or exists(select 1 from public.leadgen_leads l where regexp_replace(lower(l.business_name),'[^a-z0-9]','','g')=s.name_key
   or (s.phone_key<>'' and right(regexp_replace(coalesce(l.phone,''),'[^0-9]','','g'),10)=s.phone_key)
   or (s.website_key<>'' and regexp_replace(regexp_replace(lower(coalesce(l.website,'')),'^https?://(www\.)?','','g'),'/$','','g')=s.website_key)) as existing_match,
 exists(select 1 from public.crm_dnc_suppressions d where d.status='active' and d.removed_at is null
   and d.block_phone=true and s.phone_key<>'' and right(d.normalized_phone,10)=s.phone_key) as dnc_match
 from ottawa_source s
) x;
do $ottawa$
declare
  v_campaign uuid;
  v_goodness uuid;
  v_admin uuid;
  v_no uuid;
  v_web uuid;
  v_review uuid;
begin
  if exists (select 1 from public.call_list_segments where crm='lead_generation' and source_file_name='campaign-125288-search-924570-painters_ottawa-on-canada_cd1314b9cddb0d0a71e0c17c81e970a3.csv') then
    raise exception 'Ottawa Painters source file already imported; inspect existing segments before retrying';
  end if;
  select c.id into strict v_campaign
  from public.leadgen_campaigns c join public.leadgen_clients cl on cl.id=c.client_id
  where cl.name='Hidebrandt Web Services' and cl.active=true
    and c.name='Hidebrandt Web Services – Website Services Lead Generation' and c.status='active';
  select id into strict v_goodness from auth.users where email='ogbonnagoodness44@gmail.com';
  select id into strict v_admin from auth.users where email='cjamadiwins@gmail.com';

  insert into public.call_list_segments
    (crm,name,leadgen_campaign_id,status,created_by,campaign_name,industry,territory,source_file_name,source_file_type,total_uploaded_rows,deployed_at,deployed_by)
  values ('lead_generation','Painters — Ottawa, Ontario — No Website — Goodness Ugbana',v_campaign,'active',v_admin,
      'Hidebrandt Web Services – Website Services Lead Generation','Painting Companies','Ottawa, Ontario','campaign-125288-search-924570-painters_ottawa-on-canada_cd1314b9cddb0d0a71e0c17c81e970a3.csv','csv',0,now(),v_admin)
  returning id into v_no;
  insert into public.call_list_segments
    (crm,name,leadgen_campaign_id,status,created_by,campaign_name,industry,territory,source_file_name,source_file_type,total_uploaded_rows,deployed_at,deployed_by)
  values ('lead_generation','Painters — Ottawa, Ontario — Website Review — Goodness Ugbana',v_campaign,'active',v_admin,
      'Hidebrandt Web Services – Website Services Lead Generation','Painting Companies','Ottawa, Ontario','campaign-125288-search-924570-painters_ottawa-on-canada_cd1314b9cddb0d0a71e0c17c81e970a3.csv','csv',0,now(),v_admin)
  returning id into v_web;
  insert into public.call_list_segments
    (crm,name,leadgen_campaign_id,status,created_by,campaign_name,industry,territory,source_file_name,source_file_type,total_uploaded_rows)
  values ('lead_generation','Painters — Ottawa, Ontario — Review Required — Admin Only',v_campaign,'draft',v_admin,
      'Hidebrandt Web Services – Website Services Lead Generation','Painting Companies','Ottawa, Ontario','campaign-125288-search-924570-painters_ottawa-on-canada_cd1314b9cddb0d0a71e0c17c81e970a3.csv','csv',0)
  returning id into v_review;

  insert into public.call_list_segment_agents(segment_id,agent_id)
  values (v_no,v_goodness),(v_web,v_goodness);

  insert into public.call_list_leads
    (segment_id,source_row_number,business_name,phone,email,website,street_address,city,province,postal_code,country,industry,notes,
     extra_fields,is_possible_duplicate,duplicate_reason,dnc_flag,assigned_agent_id,created_by)
  select case bucket when 'no_website' then v_no when 'website_review' then v_web else v_review end,
    n,name,phone,email,website,address,city,'ON',postal,'Canada','Painting Companies',
    case bucket when 'no_website' then 'No website URL in source; verify before outreach.'
      when 'website_review' then 'Website present; review for redesign, presentation and SEO opportunity without presuming a defect.'
      else review_reason end,
    jsonb_build_object('source_file','campaign-125288-search-924570-painters_ottawa-on-canada_cd1314b9cddb0d0a71e0c17c81e970a3.csv','source_address',address,
      'source_category',category,'source_search_type',search_type,'source_status',source_status,
      'website_category',bucket,'review_reason',review_reason),
    (shared_phone or shared_website),case when shared_phone or shared_website then review_reason end,dnc_match,
    case when bucket in ('no_website','website_review') then v_goodness else null end,v_admin
  from ottawa_classified where bucket in ('no_website','website_review','review_required');

  update public.call_list_segments s
  set total_uploaded_rows=(select count(*) from public.call_list_leads l where l.segment_id=s.id)
  where s.id in (v_no,v_web,v_review);
end;
$ottawa$;
